-- 3D Baskı ve Üretim (T3 6.1, 6.2, 6.3, 11.1) altyazıları: LlTHmas3Eb0, fHkDJruX5QQ, ZNdPAWAy0e8, oH8WHD_mcDw.
-- Kaynak: oynatıcının otomatik Türkçe altyazısı (hızlı oynatılıp toplandı; ASR hataları olabilir).
-- Her sorunun kaynak video id ve altyazıdan alıntısı aşağıdaki yorumlardadır.
-- 3D Baskı ve Üretim orta/zor quizlerine EKLENİR. Idempotent: aynı soru metni varsa atlanır.

begin;

-- fHkDJruX5QQ kaynak: tolerans ayarı, baskı yönü, bakım ve onarım. Birbirine geçen parçaların sorunsuz bir şekilde birleşebilmesi gerekir; tasarım sürecinde önceden test parçaları üreterek ideal toleransları belirlemek montaj aşamasında yaşanabilecek problemleri en aza indirir.
-- fHkDJruX5QQ kaynak: üç boyutlu yazıcılar hassas cihazlardır ve düzenli bakım gerektirir. Yazıcının bakımı ve tamiri konusunda deneyimli bir kişi tarafından yapılması baskı kalitesinin korunması açısından önemlidir.
-- ZNdPAWAy0e8 kaynak: kompozit üretiminde en yaygın kullanılan takviyeler karbon fiber ve cam elyafıdır. Bu malzemelerin bütünlüğünü sağlamak ve yapıyı güçlendirmek için reçine ile birleştirilirler ve hafif ve yüksek mukavemetli parçalar üretmek mümkün hale gelir.
-- ZNdPAWAy0e8 kaynak: kompozit ürün üretirken maliyet, teknik bilgi ve tecrübe ve prototipleme özellikle değerlendirilmelidir. Her bir yöntemin kendi avantajları ve dezavantajları olduğundan üretim sürecine başlamadan önce bu teknikleri araştırarak en uygun seçeneği belirlemek önemlidir.
-- oH8WHD_mcDw kaynak: gövde tasarımımı iki eksenli sıcak tel kesim makinesine gönderdim... bu makine elektrikle çalışıyor ve teli elektrikle ısıtıyor. Tele herhangi bir temas durumunda hem elektrik çarpacaktır hem de canınız yanacaktır. Kesim yaptığım parçayı da asla hareket ettirmemeliyim.
-- oH8WHD_mcDw kaynak: bir insansız hava aracı üretirken elbette makinelarınız olmayabilir, üretim yöntemleriniz kısıtlı olabilir, bütçeniz olmayabilir ama vazgeçmeyeceksiniz. Alternatif yöntemleri muhakkak arayarak bulmanız gerekiyor. Manuel kesim yöntemlerini deneyebilir veya bu tür kesimleri yapanlara çizimlerinizi gönderip yaptırabilirsiniz.
-- LlTHmas3Eb0 kaynak: bir insansız hava aracının üretimi için temel malzemeler: köpük, fotoblok, depron, balsa, üç boyutlu parçalar ve kompozit parçalar.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = '3D Baskı ve Üretim' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: 3D Baskı ve Üretim orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoya göre birbirine geçen parçalar için ideal toleranslar nasıl belirlenir?","a":"Bu yöntem montaj aşamasında yaşanabilecek problemleri en aza indirir.","o":[["Tasarım sürecinde önceden test parçaları üretilerek",true],["Toleransa hiç bakılmaz",false],["Parçalar zorla birleştirilir",false],["Yalnızca yazıcı ayarına güvenilir",false]]},{"m":"3B yazıcının bakımı için videoda ne söylenir?","a":"Bakım baskı kalitesinin korunması açısından önemlidir.","o":[["Hassas cihazlardır, düzenli bakım gerekir; bakım ve tamir deneyimli biri tarafından yapılmalıdır",true],["Bakım gerektirmez",false],["Yalnızca arıza olunca bakılır",false],["Her kullanıcı kendi başına modifiye etmelidir",false]]},{"m":"Videoya göre kompozit üretiminde en yaygın takviyeler ve bağlayıcı nedir?","a":"Sonuç hafif ve yüksek mukavemetli parçalardır.","o":[["Karbon fiber ve cam elyafı takviyeleri; reçine ile birleştirilirler",true],["Çelik ve alüminyum; kaynakla birleştirilir",false],["Ahşap ve kâğıt; yapıştırıcıyla",false],["Plastik ve cam; ısıyla",false]]},{"m":"Videoya göre kompozit üretim yöntemi seçilirken neler değerlendirilmelidir?","a":"Her yöntemin avantaj ve dezavantajı olduğundan önce araştırma yapılmalıdır.","o":[["Maliyet, teknik bilgi ve tecrübe ve prototipleme",true],["Yalnızca rengi",false],["Yalnızca reçinenin markası",false],["Hiçbiri, tek bir yöntem vardır",false]]},{"m":"Sıcak tel kesim makinesiyle çalışırken videoda hangi güvenlik uyarıları verilir?","a":"Parça hareket ettirilirse beklenenden çok farklı bir parça ortaya çıkabilir.","o":[["Tel elektrikle ısıtıldığı için ona dokunulmamalı; kesim sırasında parça asla hareket ettirilmemeli",true],["Tel soğuk olduğu için dokunmak serbesttir",false],["Kesim sırasında parça elle tutularak yönlendirilmelidir",false],["Makine çalışırken sıcaklık sürekli en yükseğe alınmalıdır",false]]},{"m":"Makine imkânı olmayanlar için videoda hangi alternatif öneriliyor?","a":"Üretim yöntemleri kısıtlı olsa da alternatif yollar aranmalıdır.","o":[["Manuel kesim yöntemleri veya kesimi yapanlara çizimleri gönderip yaptırmak",true],["Projeden vazgeçmek",false],["Yalnızca hazır kit satın almak",false],["Üretimi ertelemek",false]]},{"m":"Videoya göre İHA üretiminde yaygın kullanılan temel malzemeler hangileridir? (birden çok)","a":"Her malzemenin avantaj ve dezavantajları vardır; önceliklere göre seçilmelidir.","o":[["Köpük, fotoblok ve depron",true],["Balsa",true],["Üç boyutlu baskı parçalar ve kompozit parçalar",true],["Dökme demir",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

-- fHkDJruX5QQ kaynak: baskı yönü parçaların dayanıklılığı açısından büyük önem taşır. Parçanın maruz kalacağı yükler ve bu yüklerin yönü dikkate alınarak baskı yönü ayarlanmalıdır. Eğer yük baskı katmanlarına dik olarak uygulanırsa parça esnek olabilir ancak kırılma riski azalır; yük paralel uygulandığında ise parçanın mukavemeti azalabilir.
-- ZNdPAWAy0e8 kaynak: iki ana yöntem: kaplama yöntemi ve kalıba serme yöntemi. Kaplama yönteminde bir kalıp kullanılmadan belirli bir yüzeyin üzerine kompozit malzeme kaplanır; kalıba serme yönteminde malzemeler bir kalıp içerisine yerleştirilerek şekillendirilir.
-- ZNdPAWAy0e8 kaynak: köpükten yapılmış bir kanadın üzerine cam elyafı ve reçine uygulandığını görüyoruz. Bu yöntem parçaların ağırlığını fazla arttırmadan yüksek dayanım sağlar. Özellikle insansız hava araçlarını yeni keşfedenler için bu teknik hem uygulaması kolay hem de oldukça etkili bir yöntemdir.
-- ZNdPAWAy0e8 kaynak: kalıba sererek kompozit üretmek için farklı yöntemler: elle yatırma en yaygın ve en basit; vakum torbalama: elle yatırılan malzemenin üzerine vakum torbası geçirilerek fazla reçinenin dışarı atılması ve parçanın kalıba tam oturması; vakum infüzyon: reçine vakum yardımıyla malzemeye eşit şekilde yaydırılır ve yüksek mukavemet elde edilir.
-- oH8WHD_mcDw kaynak: bizim parçamız iki boyutlu olduğu için kesim yapabiliyoruz. Daha karmaşık parçalar için iki eksenli yeterli olmayabilir, üç eksenli makineler de kullanılabilir.
-- oH8WHD_mcDw kaynak: lazer kesim makinesi ahşap ve fotoblok gibi malzemelerin kesimini yapabiliyor; türevleriyle metal malzemelere kadar... Gövdenin yan duvar parçalarını ve kuyruk parçalarını fotobloğun üzerine çizim yaptıracağım, kesim yapmayacağım çünkü makinenin gücü kesmek için yeterli değil... fotoblok üzerine cetvelle çizim yapabilirdim.
-- oH8WHD_mcDw kaynak: kapak parçalarım, kilit mekanizmam, motor aparatım ve kanadın gövdeye montajlayacak parçalarımı üç boyutlu yazıcıyla üreteceğim... yazıcının yaklaşık 2-3 dakikalık bir ısınma süresi var.
-- oH8WHD_mcDw kaynak: iki parça üst üste kesildiği için aralarında herhangi bir bağlantı olmaması gerekiyor... sıcaklığım biraz düşmüş, onu arttırmam gerekiyor yoksa makine zorlanabilir, bu da parçamda istenmeyen pürüzler demek... parçayı alacağım, ilk iş ısıyı kapatıyorum.
-- LlTHmas3Eb0 kaynak: XPS daha ince tanecikli, sert ve pürüzsüz bir yüzeye sahiptir ancak kırılgan olduğu için darbelere karşı daha hassastır. EPP ise daha kalın tanecikli ve esnek bir yapıya sahiptir, darbelere karşı daha dayanıklıdır.
-- LlTHmas3Eb0 kaynak: köpük karmaşık geometrilere sahip detaylı şekillerin oluşturulmasında sınırlı bir malzemedir. Yüksek nem köpüğün kullanım ömrünü kısaltır. Mekanik dayanımı düşük... karbon fiber çubuklar veya strip destekler ile güçlendirilmesi gerekebilir; cam elyafı veya karbon fiber kumaş serimi.
-- LlTHmas3Eb0 kaynak: bir malzemenin tamir edilebilir olması özellikle test ve AR-GE amaçlı üretilen hava araçları için büyük önem taşır. Bu tür araçlar test süreçlerinde sıkça kazalara karışabilir... tamiri zor veya maliyetli ise zaman ve bütçe kaybına yol açar.
-- LlTHmas3Eb0 kaynak: fotoblok iki tarafı ince karton kaplı, içi yoğun köpükten oluşan hafif ve sert bir malzemedir. Oldukça kırılgandır ve kırıkların tamiri genellikle zordur. Kesimi pratiktir, maket bıçağı ile şekillendirilebilir. Küçük boyutlu İHA'ların kuyruk üretiminde yaygındır. Kırılgan ve neme dayanıksızdır.
-- LlTHmas3Eb0 kaynak: depron fotoblok gibi karton kaplamaya sahip olmayan bir köpük malzemesidir; fotoblok kadar dayanıklı olmasa da oldukça esnektir... hassas ve detaylı parçaların oluşturulması özenli el işçiliği gerektirir... büyük ölçekli modellerde karbon çubuklar veya hafif profillerle güçlendirilerek rijitlik kazandırılır.
-- LlTHmas3Eb0 kaynak: balsa hafifliği ve yüksek mukavemeti ile bilinen bir ahşap türüdür. Maket bıçağı veya lazer kesici ile şekillendirilebilir. Karmaşık geometri zor, genellikle kanat ve gövdenin iç iskeleti için tercih edilir. Darbeye dayanıklılığı düşüktür, neme karşı hassastır; korunmak için özel kaplamalar veya suya dayanıklı vernikler.
-- LlTHmas3Eb0 kaynak: üç boyutlu yazıcılarla karmaşık geometrili parçalar üretilebilir; ancak baskı hacmi sınırlıdır, büyük parçalar bölünerek basılır; tasarım hataları ancak üretimde fark edilir; üç boyutlu baskıyla üretilen parçalar genellikle hafif olmaz ve yüksek dayanım sunmayabilir. Küçük parçalar, bağlantı elemanları ve mekanizmalarda yaygındır.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = '3D Baskı ve Üretim' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: 3D Baskı ve Üretim zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoya göre baskı yönü nasıl belirlenir ve yükün katmanlara göre yönü ne etkiler?","a":"Yük yönü ile baskı yönü birlikte düşünülmelidir.","o":[["Parçanın maruz kalacağı yük ve yönüne göre belirlenir; yük katmanlara dik ise esneklik artar ve kırılma riski azalır, paralel ise mukavemet azalabilir",true],["Baskı yönünün dayanıma etkisi yoktur",false],["Her zaman en hızlı baskı yönü seçilir",false],["Yük katmanlara paralel olduğunda parça en güçlüdür",false]]},{"m":"Kompozit üretimin iki ana yöntemi ve farkı videoda nasıl anlatılır?","a":"Kaplamada köpük ve fotoblok gibi hafif malzemelerin üzerine kompozit uygulanarak dayanım artırılır.","o":[["Kaplama: kalıp kullanılmadan yüzey üzerine kompozit kaplanır; kalıba serme: malzeme kalıp içine yerleştirilip şekillendirilir",true],["Kaplama kalıp gerektirir, kalıba serme gerektirmez",false],["İkisi de CNC ile yapılır",false],["Kaplama sadece metal parçalar içindir",false]]},{"m":"Köpük kanat üzerine cam elyafı ve reçine uygulamanın avantajı nedir?","a":"Yöntem kalıp gerektirmeyen kaplama yöntemidir.","o":[["Ağırlığı fazla artırmadan yüksek dayanım sağlar; yeni başlayanlar için uygulaması kolay ve etkilidir",true],["Kanadı ağırlaştırarak stabiliteyi artırır",false],["Kalıp gerektirir ve zordur",false],["Yalnızca süs amaçlıdır",false]]},{"m":"Kalıba serme yöntemlerinin farkları videoda nasıl anlatılır?","a":"Kalıp üretimi 3B modelleme, CNC işleme veya el işçiliği ile yapılır; kanat gibi uzun parçaların kalıbı zahmetlidir.","o":[["Elle yatırma en basit olanıdır; vakum torbalama fazla reçineyi atıp parçayı kalıba oturtur; vakum infüzyonda reçine vakumla eşit yayılır ve yüksek mukavemet elde edilir",true],["Hepsi aynı yöntemdir",false],["Vakum infüzyon elle yapılır ve en basit olanıdır",false],["Elle yatırma en yüksek mukavemeti verir",false]]},{"m":"İki eksenli sıcak tel kesim makinesi hangi parçalar için uygundur?","a":"Gövde ve kanat parçaları bu makineyle kesilmiştir.","o":[["İki boyutlu (düzlemsel) parçalar için; daha karmaşık parçalar için üç eksenli makineler gerekebilir",true],["Her türlü karmaşık 3B parça için",false],["Yalnızca metal parçalar için",false],["Yalnızca plastik parçalar için",false]]},{"m":"Videoda lazer kesim makinesi neden yalnızca çizim için kullanılmıştır?","a":"Lazer makineleri ahşap ve fotobloğu, türevleri ise metali de kesebilir.","o":[["Makinenin gücü fotobloğu kesmeye yetmediği için; çizgiler kesim için referans oluşturur (makine yoksa cetvelle çizilebilir)",true],["Lazer fotobloğu eritip bozduğu için",false],["Çizim lazerle kesimden daha hızlı olduğu için",false],["Lazer yalnızca metal kestiği için",false]]},{"m":"Videoda hangi parçalar 3B yazıcıyla üretilir?","a":"Gövde ve kanat ise köpükten sıcak tel kesimle üretilmiştir.","o":[["Kapak parçaları, kilit mekanizması, motor aparatı ve kanadın gövdeye montaj parçaları",true],["Gövde ve kanadın tamamı",false],["Yalnızca pervane",false],["Yalnızca elektronik kartlar",false]]},{"m":"Sıcak tel kesimde sıcaklık düşerse ne olur ve parça alınırken ne yapılır?","a":"Telin sıcaklığı parçayı eritebileceği için işlem hızlı yapılmalıdır.","o":[["Makine zorlanır ve parçada istenmeyen pürüzler oluşur, bu yüzden sıcaklık artırılır; parça alınmadan önce ısı kapatılır",true],["Parça daha pürüzsüz olur",false],["Tel kopar ve makine kapanır",false],["Sıcaklık önemli değildir, ısı hep açık kalır",false]]},{"m":"XPS ve EPP köpük türleri arasındaki fark videoda nasıl anlatılır?","a":"Köpük hafif, düşük maliyetli ve kolay işlenebilir bir malzemedir; sıcak tel kesimle şekillendirilir.","o":[["XPS ince tanecikli, sert, pürüzsüz ama kırılgandır; EPP kalın tanecikli, esnek ve darbeye daha dayanıklıdır",true],["XPS esnek ve darbeye dayanıklı; EPP sert ve kırılgandır",false],["İkisi arasında fark yoktur",false],["XPS yalnızca balsa ile kullanılır",false]]},{"m":"Köpüğün sınırlamaları ve güçlendirme yolları videoda nasıl anlatılır?","a":"Tamiri de kolaydır: parçalar sıcak silikonla monte edilir veya onarılır.","o":[["Karmaşık geometriler için sınırlıdır, nem ömrünü kısaltır, dayanımı düşüktür; karbon fiber çubuk/strip veya cam elyafı/karbon fiber kumaş serimiyle güçlendirilir",true],["Karmaşık şekillere çok uygundur ve neme dayanıklıdır",false],["Güçlendirilemez",false],["Yalnızca boyayla güçlendirilir",false]]},{"m":"Malzemenin tamir edilebilir olması İHA için neden önemlidir?","a":"Asıl amaç testlerin sağlıklı biçimde tamamlanmasıdır.","o":[["Test ve AR-GE araçları sık kazaya karışabilir; tamiri zor veya pahalıysa zaman ve bütçe kaybı olur, yeni başlayanlar için kolay tamir avantajdır",true],["Daha güzel görünmesi için",false],["Uçuş süresini artırmak için",false],["Önemli değildir",false]]},{"m":"Fotoblok için videoda hangisi doğrudur?","a":"Kompozit kaplamalarla güçlendirilebilir, ancak ağırlık da artar.","o":[["Her iki yüzü karton kaplı, içi yoğun köpük; hafif ve sert ama kırılgandır, tamiri zordur, nemden etkilenir, kuyruk üretiminde yaygındır",true],["Esnek ve nemden etkilenmeyen bir ahşaptır",false],["Metal bir malzemedir",false],["Yalnızca 3B yazıcıyla işlenir",false]]},{"m":"Depron fotobloktan nasıl ayrılır?","a":"Hafif ve şekil alabilen yapısı sayesinde iç iskelette ve dış yüzeyde kullanılabilir.","o":[["Karton kaplaması yoktur; fotoblok kadar dayanıklı olmasa da esnektir, büyük modellerde karbon çubuk/profil ile rijitlik kazandırılır",true],["Karton kaplıdır ve çok sert",false],["Ahşaptır",false],["Yalnızca lazerle kesilir",false]]},{"m":"Balsa için videoda hangisi doğrudur?","a":"Köpük, fotoblok, depron ve balsa yüzeyleri termal filmle kaplanarak pürüzsüzleştirilebilir ve neme karşı korunabilir.","o":[["Hafif ve yüksek mukavemetli bir ahşaptır; iç iskelette tercih edilir; darbeye dayanıksız, neme hassastır, vernik veya kaplama gerekir",true],["Ağır ve neme dayanıklıdır",false],["Yalnızca 3B yazıcıyla işlenir",false],["Karmaşık geometri için en uygun malzemedir",false]]},{"m":"3B yazıcıyla İHA parçası üretmenin avantaj ve sınırlamaları videoda nasıl anlatılır?","a":"Örnek: kanat montaj parçaları, motor sabitleme aparatı ve kapak kilidi 3B yazıcıyla üretilmiştir.","o":[["Karmaşık geometri ve esneklik avantajdır; baskı hacmi sınırlı, büyük parçalar bölünür, hatalar üretimde fark edilir, parçalar genellikle hafif ve çok dayanıklı olmaz; küçük parça ve mekanizmalarda yaygındır",true],["Büyük gövdeleri tek parça ve çok hafif basar",false],["Tasarım hatası yaşanmaz",false],["Yalnızca ana taşıyıcı parçalar için idealdir",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

commit;
